schema_ddl:
CREATE TABLE dipartimenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_struttura TEXT NOT NULL UNIQUE
);

CREATE TABLE personale_accademico (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    id_dipartimento INT NOT NULL REFERENCES dipartimenti(id),
    email TEXT NOT NULL UNIQUE CHECK (email ~* '^[A-Za-z0-9._%-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,4}$')
);
